// Regenerates src/schema/emoji.ts from the emoji list the web editor uses
// (gitHubEmojis of @tiptap/extension-emoji). src/schema/__tests__/emoji.test.ts
// fails when the generated file and the package drift.
import { writeFileSync } from 'node:fs'
import { gitHubEmojis } from '@tiptap/extension-emoji'

const map = {}
for (const item of gitHubEmojis) {
  if (!item.emoji) continue
  for (const code of item.shortcodes) if (!(code in map)) map[code] = item.emoji
}
const body = `// GENERATED by scripts/gen-schema-emoji.mjs from @tiptap/extension-emoji gitHubEmojis. Do not edit.
// Shortcode → emoji character, as the web editor renders an emoji node.
export const EMOJI: Readonly<Record<string, string>> = ${JSON.stringify(map)}
`
writeFileSync(new URL('../src/schema/emoji.ts', import.meta.url), body)
console.log(`wrote ${Object.keys(map).length} shortcodes`)
